sites.find:
quest_spawn_builder_t builder((quest_entry_original_t *)entries);
int x = 256;
int trigger_time_ms = 500;
quest_entry_original_t *spawn = builder.spawns;
while (x < 688) {
    spawn->pos = quest_vec2_t((float)x, 256.0f);
    spawn->set_spawn(
        SPAWN_ID_DEN_SPIDER_WEAK_10,
        trigger_time_ms,
        1);
    ++builder.count;
    ++spawn;
    x += 72;
    trigger_time_ms += 900;
}

int path_index = builder.count;
int y = 256;
trigger_time_ms = 5900;
spawn = &builder.spawns[builder.count];
while (y < 688) {
    ++spawn;
    spawn[-1].pos = quest_vec2_t(688.0f, (float)y);
    spawn[-1].template_id = SPAWN_ID_DEN_SPIDER_WEAK_10;
    spawn[-1].trigger_time_ms = trigger_time_ms;
    spawn[-1].count = 1;
    ++builder.count;
    ++path_index;
    y += 72;
    trigger_time_ms += 900;
}

int entry_count = builder.count;

